const express = require('express');
const router = express.Router();
const ActivityEvent = require('../models/ActivityEvent');
const { protect } = require('../middleware/auth');

// Users can only review their own recent activity. Platform-wide reports are generated by the owner-only CLI export.
router.get('/activity', protect, async (req, res) => {
    try {
        const limit = Math.min(100, Math.max(1, Number.parseInt(req.query.limit, 10) || 30));
        const events = await ActivityEvent.find({ user: req.user._id })
            .sort({ createdAt: -1 }).limit(limit).select('event summary createdAt').lean();
        res.json({ events });
    } catch (error) {
        console.error('Account activity lookup failed:', error.message);
        res.status(500).json({ message: 'Could not retrieve account activity' });
    }
});

module.exports = router;
